/* ============================================================================
   城東テクノ 様 商品データ登録スクリプト（MySQL）

   対象   : `ExcutionBudget`.`RDS_PRD` または `ExcutionBudget`.`RDS_TEST`
            （下の「設定」の @target_table で切り替える）
   元資料 : 商品マスタ_サンユー販売様向け20260615修正 (1).xlsx（商品マスタ）
   件数   : 2067 件

   ---------------------------------------------------------------------------
   ★ Excel 列 → テーブル列の対応 ★

     （固定値）                    → manufacturer = '城東テクノ'
     A 品番-productnumber          → productnumber
     B 品名-product_name           → product_name
     C 色-color                    → color
     D 数量-case                   → case
     E 単位-case_unit              → case_unit
     F 入数-quantity               → quantity
     G 単位quantity_unit           → quantity_unit
     H 正価/ケース-standard_price  → standard_price  ※「オープン価格」（100 件）は 0
     I 長さ-length                 → length

   ---------------------------------------------------------------------------
   ★ 仕組み ★

     MySQL はテーブル名に変数を直接使えないため、次の手順で登録する。

       1. 登録先と同じ構成の一時テーブル `ExcutionBudget`.`tmp_import_joto` を作り、
          全データをそこへ INSERT する（一時テーブル名は固定なので変数不要）
       2. 一時テーブル → @target_table へ INSERT ... SELECT する
          （この文だけ変数から組み立てて PREPARE / EXECUTE で実行）

     一時テーブルは接続（セッション）を切ると自動で消える。
     変数（@target_table など）も接続ごとに消えるため、接続し直した場合は
     「設定」から実行し直すこと。

   ★ id ★

     INSERT では id を指定しない（登録先の AUTO_INCREMENT で採番される）。

   進め方 : 設定 → STEP 0 → 1 → 2 → 3 → 4 → COMMIT → 5 の順に、
            各ブロックを選択して実行する。
   ============================================================================ */


/* ============================================================================
   設定 : ★ 登録先はここだけ変更する ★
   ---------------------------------------------------------------------------
   'RDS_TEST' または 'RDS_PRD'
   ============================================================================ */
SET @target_table = 'RDS_TEST';

SET @manufacturer = '城東テクノ';   -- 変更不要


/* ============================================================================
   STEP 0 : 開いているトランザクションを閉じる（毎回最初に実行）
   ============================================================================ */
ROLLBACK;

SELECT @target_table AS target_table;   -- 登録先が正しいか必ず目視確認する


/* ============================================================================
   STEP 1 : 登録済みでないか確認する
   ---------------------------------------------------------------------------
   → 0 件なら STEP 2 へ
   → 件数が出たら既に登録済み。二重登録になるため中止して確認する
   ============================================================================ */
SET @sql = CONCAT('SELECT COUNT(*) AS registered_rows FROM `ExcutionBudget`.`', @target_table,
                  '` WHERE `manufacturer` = ?');
PREPARE stmt FROM @sql;
EXECUTE stmt USING @manufacturer;
DEALLOCATE PREPARE stmt;


/* ============================================================================
   STEP 2 : 一時テーブルを作り、全データを入れる
   ============================================================================ */
DROP TEMPORARY TABLE IF EXISTS `ExcutionBudget`.`tmp_import_joto`;

SET @sql = CONCAT('CREATE TEMPORARY TABLE `ExcutionBudget`.`tmp_import_joto` LIKE `ExcutionBudget`.`', @target_table, '`');
PREPARE stmt FROM @sql;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;

