SELECT COUNT(*) AS tmp_rows FROM `ExcutionBudget`.`tmp_import_joto`;


/* ============================================================================
   STEP 3 : 一時テーブル → 登録先へ INSERT
   ============================================================================ */
START TRANSACTION;

SELECT @target_table AS target_table;   -- 登録先が正しいか必ず目視確認する

SET @sql = CONCAT('INSERT INTO `ExcutionBudget`.`', @target_table, '` ',
                  '(`manufacturer`, `productnumber`, `product_name`, `color`, `case`, `case_unit`, `quantity`, `quantity_unit`, `standard_price`, `length`) ',
                  'SELECT `manufacturer`, `productnumber`, `product_name`, `color`, `case`, `case_unit`, `quantity`, `quantity_unit`, `standard_price`, `length` ',
                  'FROM `ExcutionBudget`.`tmp_import_joto` ORDER BY `id`');
PREPARE stmt FROM @sql;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;


/* ============================================================================
   STEP 4 : 登録結果を確認する
   ---------------------------------------------------------------------------
   → inserted_rows が 2067 なら COMMIT
   → 違えば ROLLBACK
   ============================================================================ */
SET @sql = CONCAT('SELECT COUNT(*) AS inserted_rows, MIN(`id`) AS min_id, MAX(`id`) AS max_id ',
                  'FROM `ExcutionBudget`.`', @target_table, '` WHERE `manufacturer` = ?');
PREPARE stmt FROM @sql;
EXECUTE stmt USING @manufacturer;
DEALLOCATE PREPARE stmt;


/* ============================================================================
   確定（STEP 4 で件数が正しいことを確認してから実行）
   ============================================================================ */
-- COMMIT;
-- ROLLBACK;


/* ============================================================================
   STEP 5 : 後片付け（COMMIT / ROLLBACK の後に実行）
   ============================================================================ */
DROP TEMPORARY TABLE IF EXISTS `ExcutionBudget`.`tmp_import_joto`;
